<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api, type BuildMaterial, type ConstructionRecord, type RecyclingRecord, type TransportRecord } from '@/api'

const route = useRoute(); const router = useRouter(); const projectId = Number(route.params.id)
const project = ref<any>(null); const active = ref('overview'); const loading = ref(true); const error = ref('')
const build = ref<BuildMaterial[]>([]); const transport = ref<TransportRecord[]>([]); const construction = ref<ConstructionRecord[]>([]); const recycling = ref<RecyclingRecord[]>([]); const analysis = ref<any>(null); const versions = ref<any[]>([])
const buildFactors = ref<any[]>([]); const transportFactors = ref<any[]>([])
const materialForm = reactive({ factorConfigId: 0, quantity: 1, unitPrice: 0, marketPrice: null as number | null }); const transportForm = reactive({ factorConfigId: 0, transportedMaterial: '', transportQuantity: 1, transportDistance: 1, transportUnitPrice: 0 }); const constructionForm = reactive({ machineryName: '', energyType: '电力', shiftCount: 1, energyPerShift: 1, shiftUnitPrice: 0 }); const recyclingForm = reactive({ materialName: '', materialType: '其他', recyclingQuantity: 1, recyclingFactor: 0, recyclingCoefficient: 0, recyclingUnitPrice: 0 })
const title = computed(() => project.value?.projectName || '项目工作区')
async function load() { loading.value = true; try { const [p, b, t, c, r, a, v, bf, tf] = await Promise.all([api.get(`/projects/${projectId}`), api.get(`/projects/${projectId}/build-materials`), api.get(`/projects/${projectId}/transport-records`), api.get(`/projects/${projectId}/construction-records`), api.get(`/projects/${projectId}/recycling-records`), api.get(`/projects/${projectId}/analysis`), api.get(`/projects/${projectId}/versions`), api.get(`/projects/${projectId}/build-factors`), api.get(`/projects/${projectId}/transport-factors`)]); project.value=p.data; build.value=b.data; transport.value=t.data; construction.value=c.data; recycling.value=r.data; analysis.value=a.data; versions.value=v.data; buildFactors.value=bf.data; transportFactors.value=tf.data; if (!materialForm.factorConfigId) materialForm.factorConfigId=bf.data[0]?.id || 0; if (!transportForm.factorConfigId) transportForm.factorConfigId=tf.data[0]?.id || 0 } catch (e: any) { error.value=e.response?.data?.message || '无法加载项目' } finally { loading.value=false } }
async function refresh() { const [b,t,c,r,a,v]=await Promise.all([api.get(`/projects/${projectId}/build-materials`),api.get(`/projects/${projectId}/transport-records`),api.get(`/projects/${projectId}/construction-records`),api.get(`/projects/${projectId}/recycling-records`),api.get(`/projects/${projectId}/analysis`),api.get(`/projects/${projectId}/versions`)]); build.value=b.data; transport.value=t.data; construction.value=c.data; recycling.value=r.data; analysis.value=a.data; versions.value=v.data }
async function addMaterial() { await api.post(`/projects/${projectId}/build-materials`, materialForm); ElMessage.success('建材记录已添加'); await refresh() }
async function addTransport() { await api.post(`/projects/${projectId}/transport-records`, transportForm); ElMessage.success('运输记录已添加'); await refresh() }
async function addConstruction() { await api.post(`/projects/${projectId}/construction-records`, constructionForm); ElMessage.success('施工记录已添加'); await refresh() }
async function addRecycling() { await api.post(`/projects/${projectId}/recycling-records`, recyclingForm); ElMessage.success('回收记录已添加'); await refresh() }
async function removeRecord(kind: string, id: number) { await api.delete(`/projects/${projectId}/${kind}/${id}`); await refresh() }
async function saveVersion() { const result=await api.post(`/projects/${projectId}/versions`); ElMessage.success(`已保存版本 v${result.data.versionNumber}`); await refresh() }
function report(versionId: number, type: 'pdf'|'excel') { window.open(`/api/projects/${projectId}/versions/${versionId}/reports/${type}`, '_blank') }
onMounted(load)
</script>
<template>
  <div v-loading="loading" class="workspace-wrap"><div class="workspace-heading"><div><button class="back-link" @click="router.push('/projects')">← 返回项目台账</button><h1>{{ title }}</h1><p class="muted">{{ project?.buildingArea?.toLocaleString() }} ㎡ · {{ project?.buildingType || '未填写类型' }} · {{ project?.accountingStandard }}</p></div><div class="heading-actions"><el-button @click="refresh">刷新</el-button><el-button type="primary" @click="saveVersion">保存核算版本</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <nav class="workspace-tabs"><button v-for="tab in [['overview','总览'],['build','建材生产'],['transport','运输'],['construction','施工'],['recycling','回收'],['analysis','分析'],['versions','版本'] ]" :key="tab[0]" :class="{active: active===tab[0]}" @click="active=tab[0]">{{ tab[1] }}</button></nav>
    <section v-if="active==='overview'" class="workspace-section"><div class="stat-grid"><div class="stat-card accent"><span>净碳排放</span><strong>{{ analysis?.emission?.netEmission?.toFixed(3) || '0.000' }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>建材生产</span><strong>{{ analysis?.build?.totalEmission?.toFixed(3) || '0.000' }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>施工阶段</span><strong>{{ analysis?.construction?.totalEmission?.toFixed(3) || '0.000' }}</strong><small>tCO₂e</small></div><div class="stat-card"><span>回收减排</span><strong>{{ analysis?.recycling?.totalReduction?.toFixed(3) || '0.000' }}</strong><small>tCO₂e</small></div></div><div class="overview-columns"><div class="panel"><div class="panel-heading"><h2>生命周期阶段</h2><span class="muted">tCO₂e</span></div><div v-for="stage in analysis?.emission?.stages" :key="stage.name" class="bar-row"><span>{{ stage.name }}</span><div class="bar-track"><i :style="{width: `${Math.min(100, Math.abs(stage.emission)/(Math.abs(analysis?.emission?.netEmission||1))*25)}%`}"></i></div><strong>{{ stage.emission.toFixed(3) }}</strong></div></div><div class="panel"><div class="panel-heading"><h2>项目概况</h2></div><dl class="detail-list"><dt>项目地点</dt><dd>{{ [project?.province, project?.cityDistrict, project?.address].filter(Boolean).join(' ') || '未填写' }}</dd><dt>结构类型</dt><dd>{{ project?.structureType || '未填写' }}</dd><dt>楼层数</dt><dd>{{ project?.floorCount || '未填写' }}</dd><dt>记录总数</dt><dd>{{ build.length + transport.length + construction.length + recycling.length }}</dd></dl></div></div></section>
    <section v-else-if="active==='analysis'" class="workspace-section"><div class="analysis-grid"><div class="panel"><div class="panel-heading"><h2>碳排放分析</h2></div><div class="analysis-number">{{ analysis?.emission?.netEmission?.toFixed(6) }} <small>tCO₂e</small></div><p class="muted">单位面积净排放 {{ analysis?.emission?.unitAreaNetEmission?.toFixed(6) }} kgCO₂e/㎡</p><div v-for="stage in analysis?.emission?.stages" :key="stage.name" class="analysis-line"><span>{{ stage.name }}</span><strong>{{ stage.emission.toFixed(6) }}</strong></div></div><div class="panel"><div class="panel-heading"><h2>成本分析</h2></div><div class="analysis-number">{{ analysis?.cost?.totalCost?.toFixed(4) }} <small>万元</small></div><p class="muted">单位面积成本 {{ analysis?.cost?.unitAreaCost?.toFixed(4) }} 元/㎡</p><div class="analysis-line"><span>单位成本碳排</span><strong>{{ analysis?.cost?.unitCostEmission?.toFixed(6) }}</strong></div><div class="analysis-line"><span>建材成本</span><strong>{{ analysis?.cost?.buildCost?.toFixed(4) }} 万元</strong></div></div></div></section>
    <section v-else-if="active==='versions'" class="workspace-section"><div class="panel"><div class="panel-heading"><div><h2>核算版本</h2><p class="muted">版本保存后数据快照不可变</p></div><el-button type="primary" @click="saveVersion">保存当前版本</el-button></div><el-table :data="versions"><el-table-column prop="versionNumber" label="版本" width="100"><template #default="scope">v{{ scope.row.versionNumber }}</template></el-table-column><el-table-column prop="createdAt" label="保存时间" /><el-table-column prop="createdBy" label="保存人" /><el-table-column label="报告" width="180"><template #default="scope"><el-button link type="primary" @click="report(scope.row.id,'excel')">Excel</el-button><el-button link type="primary" @click="report(scope.row.id,'pdf')">PDF</el-button></template></el-table-column></el-table></div></section>
    <section v-else class="workspace-section"><div class="panel"><div class="panel-heading"><div><h2>{{ active==='build'?'建材生产':active==='transport'?'运输':active==='construction'?'施工':'回收' }}记录</h2><p class="muted">数据保存后立即参与服务端核算</p></div></div><div v-if="active==='build'" class="entry-form"><el-select v-model="materialForm.factorConfigId" placeholder="选择建材因子" filterable><el-option v-for="item in buildFactors" :key="item.id" :value="item.id" :label="`${item.name} · ${item.category}`" /></el-select><el-input-number v-model="materialForm.quantity" :min="0.000001" placeholder="用量" /><el-input-number v-model="materialForm.unitPrice" :min="0" placeholder="成交价（元）" /><el-button type="primary" @click="addMaterial">添加</el-button></div><div v-else-if="active==='transport'" class="entry-form"><el-select v-model="transportForm.factorConfigId" placeholder="选择车辆"><el-option v-for="item in transportFactors" :key="item.id" :value="item.id" :label="`${item.vehicleName} · ${item.energyType}`" /></el-select><el-input v-model="transportForm.transportedMaterial" placeholder="运输货物" /><el-input-number v-model="transportForm.transportQuantity" :min="0.000001" placeholder="运输量" /><el-input-number v-model="transportForm.transportDistance" :min="0.000001" placeholder="运距" /><el-input-number v-model="transportForm.transportUnitPrice" :min="0" placeholder="运输单价" /><el-button type="primary" @click="addTransport">添加</el-button></div><div v-else-if="active==='construction'" class="entry-form"><el-input v-model="constructionForm.machineryName" placeholder="机械名称" /><el-select v-model="constructionForm.energyType"><el-option label="电力" value="电力" /><el-option label="柴油" value="柴油" /><el-option label="汽油" value="汽油" /></el-select><el-input-number v-model="constructionForm.shiftCount" :min="1" placeholder="台班数" /><el-input-number v-model="constructionForm.energyPerShift" :min="0.000001" placeholder="单位台班能耗" /><el-input-number v-model="constructionForm.shiftUnitPrice" :min="0" placeholder="台班单价" /><el-button type="primary" @click="addConstruction">添加</el-button></div><div v-else class="entry-form"><el-input v-model="recyclingForm.materialName" placeholder="材料名称" /><el-select v-model="recyclingForm.materialType"><el-option v-for="t in ['金属','保温材料','玻璃','其他']" :key="t" :label="t" :value="t" /></el-select><el-input-number v-model="recyclingForm.recyclingQuantity" :min="0.000001" placeholder="回收量" /><el-input-number v-model="recyclingForm.recyclingFactor" :min="0" placeholder="回收因子" /><el-input-number v-model="recyclingForm.recyclingCoefficient" :min="0" placeholder="回收系数" /><el-button type="primary" @click="addRecycling">添加</el-button></div>
      <el-table v-if="active==='build'" :data="build" stripe><el-table-column prop="materialName" label="材料名称"/><el-table-column prop="type" label="类型"/><el-table-column prop="quantity" label="用量"/><el-table-column prop="emissionAmount" label="碳排（t）"/><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="removeRecord('build-materials',s.row.id)">删除</el-button></template></el-table-column></el-table><el-table v-else-if="active==='transport'" :data="transport" stripe><el-table-column prop="vehicleName" label="车辆"/><el-table-column prop="transportedMaterial" label="货物"/><el-table-column prop="transportQuantity" label="运输量"/><el-table-column prop="emissionAmount" label="碳排（t）"/><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="removeRecord('transport-records',s.row.id)">删除</el-button></template></el-table-column></el-table><el-table v-else-if="active==='construction'" :data="construction" stripe><el-table-column prop="machineryName" label="机械"/><el-table-column prop="energyType" label="能源"/><el-table-column prop="shiftCount" label="台班"/><el-table-column prop="emissionAmount" label="碳排（kg）"/><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="removeRecord('construction-records',s.row.id)">删除</el-button></template></el-table-column></el-table><el-table v-else :data="recycling" stripe><el-table-column prop="materialName" label="材料"/><el-table-column prop="materialType" label="类别"/><el-table-column prop="recyclingQuantity" label="回收量"/><el-table-column prop="reductionAmount" label="减排（t）"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.isCustomMaterial" link type="danger" @click="removeRecord('recycling-records',s.row.id)">删除</el-button><span v-else class="muted">自动联动</span></template></el-table-column></el-table></div></section>
  </div>
</template>
